import { CardBodyEditor } from './card_body_editor'
import { CardDeleteDialog } from './card_delete_dialog'
import { AgentUsageDisplay } from '../agents/agent_usage_display'
import { cardAgentTokenUsage } from '../../services/agents/agent_usage'
import { CardMarkdownDataSource } from '../editor/card_markdown_data_source'
import { MarkdownDocumentHistoryStore } from '../editor/markdown_document_history_store'
import { CardBodySaveStatus } from './card_body_save_status'
import { CardCommitMenu } from './card_commit_menu'
import { CardCommitDiffPanel } from './card_commit_diff_panel'
import { useCardCommits } from '../hooks/use_card_commits'
import type { CardCommit } from '../../services/actions/card_commit_history'
import { openFilesService } from '../../services/open_files_service'
import { getProjectCard, useCardConversations, useCardMetadata } from './use_project_card'
import { useDialogError } from '../hooks/use_dialog_error'
import { dialogService } from '../../services/dialog_service'
import { isWorktreeIntegratable, worktreeService } from '../../services/project/worktree_service'
import { dataService } from '../../services/data/data_service'
import {
    cardPopupService,
    subscribeCardPopups,
    type CardDetailsPopupEntry,
} from '../../services/card_popup_service'
import { MarkdownTypeaheadLayerProvider } from '../editor/markdown_typeahead_layer_provider'
import { useProjectReadOnly } from '../hooks/use_project_read_only'

const CARD_BODY_POPOVER_WIDTH = 760
const CARD_BODY_POPOVER_HEIGHT = 620
export const CARD_BODY_POPOVER_SIZE_KEY = 'md2.cardBodyPopover.size'

function subscribeWorktrees(onStoreChange: () => void) {
    worktreeService.addEventListener('changed', onStoreChange)

    return () => worktreeService.removeEventListener('changed', onStoreChange)
}

function useBoardDocument(dataSource: CardMarkdownDataSource) {
    const subscribe = useCallback((onStoreChange: () => void) => {
        dataSource.addEventListener('activeDocumentChanged', onStoreChange)

        return () => dataSource.removeEventListener('activeDocumentChanged', onStoreChange)
    }, [dataSource])
    const getSnapshot = useCallback(() => dataSource.getActiveDocument('board-card'), [dataSource])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

interface TitleEdit {
    path: string | null
    title: string
}

interface CardBodyPopoverProps {
    cardTypes: CardTypeConfig[]
    isMobile: boolean
    onDeleteCard: (path: string) => Promise<void>
    onOpenAffects: (path: string) => void
    onOpenInFileMode: (path: string) => void
    statusColors: Map<string, string>
    visible: boolean
}

interface CardBodyPopoverEntryProps extends CardBodyPopoverProps {
    entry: CardDetailsPopupEntry
    stackPosition: number
}

/** Stable renderer for every shared-manager card-details popup. */
export function CardBodyPopover(props: CardBodyPopoverProps) {
    const entries = useSyncExternalStore(
        subscribeCardPopups,
        () => cardPopupService.getSnapshot(),
        () => cardPopupService.getSnapshot(),
    )
    const topEntryId = entries.at(-1)?.id

    return entries.map((entry, stackPosition) => entry.kind === 'card-details' ? (
        <CardBodyPopoverEntry
            {...props}
            entry={entry}
            key={entry.id}
            stackPosition={stackPosition}
            visible={props.visible && (!props.isMobile || entry.id === topEntryId)}
        />
    ) : null)
}

/** Owns one card editor and all popup-local UI state for its entry lifetime. */
function CardBodyPopoverEntry(props: CardBodyPopoverEntryProps) {
    const {
        cardTypes,
        entry,
        isMobile,
        onDeleteCard,
        onOpenAffects,
        onOpenInFileMode,
        statusColors,
        stackPosition,
        visible,
    } = props
    const readOnly = useProjectReadOnly()
    const { cardPath, diffSelection } = entry
    const anchorElement = entry.anchorElement.isConnected ? entry.anchorElement : entry.fallbackAnchorElement
    const card = useCardMetadata(cardPath)
    const activity = useCardConversations(cardPath)
    const [deleteCardPath, setDeleteCardPath] = useState<string | null>(null)
    const [dataSource] = useState(() => {
        const popupDataSource = new CardMarkdownDataSource()
        popupDataSource.init(dataService)
        return popupDataSource
    })
    const [historyStore] = useState(() => new MarkdownDocumentHistoryStore())
    const cardIdentity = card?.header.internalId
    const boardDocument = useBoardDocument(dataSource)
    const [isFullscreen, setIsFullscreen] = useState(false)
    const [popupContentElement, setPopupContentElement] = useState<HTMLDivElement | null>(null)
    const [titleEdit, setTitleEdit] = useState<TitleEdit>({ path: null, title: '' })
    const titleDraft = titleEdit.path === card?.path ? titleEdit.title : card?.header.title ?? ''
    const cardCommits = useCardCommits(card?.header.internalId ?? null)
    const worktreeRecords = useSyncExternalStore(
        subscribeWorktrees,
        () => worktreeService.getRecords(),
        () => worktreeService.getRecords(),
    )
    const assignedWorktree = card?.header.worktree
    const assignedRecord = Number.isInteger(assignedWorktree) && assignedWorktree
        ? worktreeRecords[assignedWorktree - 1]
        : null
    const currentWorktreeAvailable = !card?.header.worktreeError && isWorktreeIntegratable(assignedRecord)
    const selectedCommit = diffSelection?.kind === 'commit' && diffSelection.cardInternalId === cardIdentity
        ? diffSelection.commit
        : null
    const selectedWorktree = diffSelection?.kind === 'worktree'
    const hasSelectedDiff = !!selectedCommit || selectedWorktree
    const missingCardIdentityError = visible && card && !cardIdentity
        ? new Error(`Card identity was not added before opening: ${card.path}`)
        : null
    useDialogError(missingCardIdentityError, 'Card details could not be opened')

    useEffect(() => {
        if (!cardPath) return
        if (!cardIdentity) return
        const currentCard = getProjectCard(cardPath)
        if (!currentCard) return

        const document = openFilesService.openBoardDocument(currentCard)
        dataSource.setBoardDocument(document)

        return () => {
            dataSource.setBoardDocument(null)
            historyStore.discardDocument(document)
            openFilesService.closeBoardDocument(document)
        }
    }, [cardIdentity, cardPath, dataSource, historyStore])

    useEffect(() => () => {
        historyStore.clear()
        dataSource.dispose()
    }, [dataSource, historyStore])

    useEffect(() => {
        if (selectedWorktree && !currentWorktreeAvailable) cardPopupService.clearDiff(entry.id)
    }, [currentWorktreeAvailable, entry.id, selectedWorktree])

    useEffect(() => {
        if (diffSelection?.kind === 'commit' && diffSelection.cardInternalId !== cardIdentity) {
            cardPopupService.clearDiff(entry.id)
        }
    }, [cardIdentity, diffSelection, entry.id])

    const closePopover = () => {
        cardPopupService.close(entry.id)
    }

    const handlePopoverClose = () => {
        if (diffSelection) {
            cardPopupService.clearDiff(entry.id)
            return
        }
        closePopover()
    }

    const selectCommit = (commit: CardCommit) => {
        try {
            if (!card?.header.internalId) throw new Error('Cannot select card commit without an internal ID')
            cardPopupService.selectDiff(entry.id, { cardInternalId: card.header.internalId, commit, kind: 'commit' })
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Card commit could not be selected' })
        }
    }
    const selectWorktree = () => cardPopupService.selectDiff(entry.id, { kind: 'worktree' })
    const clearSelectedDiff = () => cardPopupService.clearDiff(entry.id)

    const openInFileMode = () => {
        if (!card) return
        setIsFullscreen(false)
        onOpenInFileMode(card.path)
    }

    const closeDeleteCardDialog = () => {
        setDeleteCardPath(null)
    }

    const openDeleteCardDialog = () => {
        if (!card) return
        setDeleteCardPath(card.path)
    }

    const openAffects = () => {
        if (card) onOpenAffects(card.path)
    }

    const handleTitleChange = (event: ChangeEvent<HTMLInputElement>) => {
        if (!card) return
        setTitleEdit({ path: card.path, title: event.target.value })
    }

    const commitTitle = () => {
        if (!card) return
        const nextTitle = titleDraft.trim()
        if (nextTitle.length === 0) {
            setTitleEdit({ path: card.path, title: card.header.title })
            return
        }
        if (nextTitle !== card.header.title) dataSource.updateActiveCardTitle('board-card', nextTitle)
    }

    const handleTitleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Enter') commitTitle()
        if (event.key === 'Escape' && card) setTitleEdit({ path: card.path, title: card.header.title })
    }

    const toggleFullscreen = useCallback(() => {
        setIsFullscreen((current) => !current)
    }, [])

    const deleteCard = async (path: string) => {
        setIsFullscreen(false)
        await onDeleteCard(path)
    }

    const titleId = card ? `card-body-popover-${card.header.internalId}` : 'card-body-popover'
    const actionContext: ActionContext = {
        ...(card?.header.internalId ? { cardInternalId: card.header.internalId } : {}),
        ...(card ? { file: card.path } : {}),
        kind: 'card',
    }
    const runningRun = useRunningActionForContext(actionContext)
    const statusLabel = runningRun ? 'Running' : 'Idle'
    const fullscreenSize = `calc(100vw - ${POPOVER_SIDE_MARGIN * 2}px)`
    const fullscreenHeight = `calc(100vh - ${POPOVER_TOP_MARGIN + POPOVER_SIDE_MARGIN}px)`

    return (
        <>
            <ResizablePopper
                anchorElement={anchorElement}
                constrainSizeToViewport
                draggable={!isMobile && !isFullscreen}
                fullHeight={isMobile}
                initialSize={{ height: CARD_BODY_POPOVER_HEIGHT, width: CARD_BODY_POPOVER_WIDTH }}
                labelId={titleId}
                onActivate={() => cardPopupService.activate(entry.id)}
                onClose={handlePopoverClose}
                open={visible && !!card && !!anchorElement}
                paperSx={{
                    backgroundColor: 'background.paper',
                    border: '1px solid',
                    borderColor: 'divider',
                    borderRadius: isMobile ? 0 : '14px',
                    boxSizing: 'border-box',
                    boxShadow: '0 24px 60px rgba(16, 24, 40, 0.28)',
                    flexDirection: 'column',
                    height: isMobile ? '100dvh !important' : isFullscreen ? `${fullscreenHeight} !important` : undefined,
                    left: isMobile ? '0 !important' : isFullscreen ? `${POPOVER_SIDE_MARGIN}px !important` : undefined,
                    margin: isMobile ? '0 !important' : undefined,
                    maxHeight: isMobile || isFullscreen ? 'none' : undefined,
                    maxWidth: isMobile || isFullscreen ? 'none' : undefined,
                    top: isMobile ? '0 !important' : isFullscreen ? `${POPOVER_TOP_MARGIN}px !important` : undefined,
                    transform: isMobile || isFullscreen ? 'none !important' : undefined,
                    width: isMobile ? '100vw !important' : isFullscreen ? `${fullscreenSize} !important` : undefined,
                }}
                resizeFromAllSides={!isFullscreen}
                resizeLabel="Resize card details popup"
                stackPosition={stackPosition}
                storageKey={isMobile ? undefined : CARD_BODY_POPOVER_SIZE_KEY}
            >
                <MarkdownTypeaheadLayerProvider stackPosition={stackPosition}>
                    {card ? (
                        <Box
                            ref={setPopupContentElement}
                            sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}
                        >
                            <Box
                                data-drag-handle={!isMobile && !isFullscreen ? 'true' : undefined}
                                sx={{
                                    alignItems: 'center',
                                    borderBottom: '1px solid',
                                    borderColor: 'divider',
                                    cursor: !isMobile && !isFullscreen ? 'move' : undefined,
                                    display: 'flex',
                                    flexShrink: 0,
                                    gap: '10px',
                                    padding: '12px 16px 12px 20px',
                                }}
                            >
                                {/* Visually hidden; provides the dialog's accessible name via aria-labelledby. */}
                                <Typography
                                    id={titleId}
                                    sx={{
                                        border: 0,
                                        clip: 'rect(0 0 0 0)',
                                        height: '1px',
                                        margin: '-1px',
                                        overflow: 'hidden',
                                        padding: 0,
                                        position: 'absolute',
                                        whiteSpace: 'nowrap',
                                        width: '1px',
                                    }}
                                >
                                    {card.header.id} card details
                                </Typography>
                                <Box
                                    component="span"
                                    sx={(theme) => ({
                                        backgroundColor: alpha(theme.palette.primary.main, theme.palette.mode === 'dark' ? 0.16 : 0.1),
                                        borderRadius: '5px',
                                        color: 'primary.main',
                                        flexShrink: 0,
                                        fontFamily: '"Roboto Mono", ui-monospace, monospace',
                                        fontSize: 12,
                                        fontWeight: 600,
                                        padding: '3px 8px',
                                    })}
                                >
                                    {card.header.id}
                                </Box>
                                <InputBase
                                    aria-label="Card title"
                                    onBlur={commitTitle}
                                    onChange={handleTitleChange}
                                    onKeyDown={handleTitleKeyDown}
                                    placeholder="Card title"
                                    readOnly={readOnly}
                                    sx={(theme) => ({
                                        '&:focus-within': {
                                            backgroundColor: 'background.paper',
                                            borderColor: 'primary.main',
                                            boxShadow: `0 0 0 3px ${alpha(theme.palette.primary.main, 0.12)}`,
                                        },
                                        '&:hover:not(:focus-within)': { backgroundColor: 'action.hover' },
                                        '& input': { height: '34px', padding: '0 10px' },
                                        backgroundColor: 'transparent',
                                        border: '1px solid transparent',
                                        borderRadius: '8px',
                                        color: 'text.primary',
                                        flex: 1,
                                        fontSize: 16,
                                        fontWeight: 700,
                                        minWidth: 0,
                                    })}
                                    value={titleDraft}
                                />
                                <CardCommitMenu
                                    commits={cardCommits.commits}
                                    currentWorktreeAvailable={currentWorktreeAvailable}
                                    error={cardCommits.error}
                                    onSelectCommit={selectCommit}
                                    onSelectWorktree={selectWorktree}
                                />
                                <Box sx={{
                                    alignItems: 'center',
                                    color: 'text.disabled',
                                    display: 'flex',
                                    flexShrink: 0,
                                    fontSize: 11.5,
                                    gap: '5px',
                                }}>
                                    <Box sx={{ backgroundColor: runningRun ? 'success.main' : 'text.disabled', borderRadius: '50%', height: 7, width: 7 }} />
                                    {statusLabel}
                                </Box>
                                <Divider orientation="vertical" sx={{ borderColor: 'divider', height: 20 }} />
                                {boardDocument ? <CardBodySaveStatus document={boardDocument} /> : null}
                            
                                <Tooltip title="Close">
                                    <IconButton aria-label="Close card details" onClick={closePopover} size="small" sx={{ height: 30, ml: '4px', width: 30 }}>
                                        <Close sx={{ fontSize: 17 }} />
                                    </IconButton>
                                </Tooltip>
                            </Box>

                            {selectedCommit || selectedWorktree ? (
                                <CardCommitDiffPanel
                                    binding="board-card"
                                    dataSource={dataSource}
                                    selection={selectedCommit ? { commit: selectedCommit, kind: 'commit' } : { kind: 'worktree' }}
                                    key={selectedCommit?.commit ?? 'current-worktree'}
                                    onExit={clearSelectedDiff}
                                />
                            ) : null}
                            <Box
                                hidden={hasSelectedDiff}
                                sx={{ display: hasSelectedDiff ? 'none' : 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}
                            >
                                <CardBodyEditor
                                    cardTypes={cardTypes}
                                    dataSource={dataSource}
                                    historyStore={historyStore}
                                    isFullscreen={isFullscreen}
                                    isMobile={isMobile}
                                    onToggleFullscreen={toggleFullscreen}
                                    overlayContainer={popupContentElement}
                                    statusColors={statusColors}
                                />
                            </Box>

                            <Box
                                sx={{
                                    alignItems: 'center',
                                    backgroundColor: 'background.default',
                                    borderTop: '1px solid',
                                    borderColor: 'divider',
                                    display: 'flex',
                                    flexShrink: 0,
                                    gap: isMobile ? '4px' : '8px',
                                    minWidth: 0,
                                    padding: isMobile ? '8px' : '12px 16px',
                                }}
                            >
                                {isMobile ? (
                                    <>
                                        <Tooltip title="Delete">
                                            <IconButton aria-label="Delete" color="error" disabled={readOnly} onClick={openDeleteCardDialog}>
                                                <DeleteOutline />
                                            </IconButton>
                                        </Tooltip>
                                        <Tooltip title="Affects">
                                            <IconButton aria-label="Affects" disabled={readOnly} onClick={openAffects}>
                                                <FolderSearchOutline />
                                            </IconButton>
                                        </Tooltip>
                                        <Tooltip title="Open in file mode">
                                            <IconButton aria-label="Open in file mode" onClick={openInFileMode}>
                                                <FileDocumentOutline />
                                            </IconButton>
                                        </Tooltip>
                                    </>
                                ) : (
                                    <>
                                        <Button color="error" disabled={readOnly} onClick={openDeleteCardDialog} startIcon={<DeleteOutline />} variant="outlined">Delete</Button>
                                        <Button disabled={readOnly} onClick={openAffects} startIcon={<FolderSearchOutline />} variant="outlined">Affects</Button>
                                        <Button onClick={openInFileMode} startIcon={<FileDocumentOutline />} variant="outlined">Open in file mode</Button>
                                    </>
                                )}
                                <AgentUsageDisplay usage={cardAgentTokenUsage(activity?.conversations ?? [])} />
                                <Box sx={{ flex: 1 }} />
                                {!isMobile ? <Button onClick={closePopover} variant="contained">Close</Button> : null}
                            </Box>
                        </Box>
                    ) : null}
                </MarkdownTypeaheadLayerProvider>
            </ResizablePopper>
            <CardDeleteDialog cardPath={visible ? deleteCardPath : null} onClose={closeDeleteCardDialog} onDeleteCard={deleteCard} />
        </>
    )
}
import { Box } from '@mui/material'
import { DndContext, DragOverlay, PointerSensor, closestCorners, useSensor, useSensors } from '@dnd-kit/core'
import type { DragEndEvent, DragOverEvent, DragStartEvent } from '@dnd-kit/core'
import { useCallback, useEffect, useRef, useState } from 'react'
import { buildCardColumns } from '../../data/card_ordering'
import type { CardTypeConfig, StateConfig } from '../../data/data_types'
import { dataService } from '../../services/data/data_service'
import { dialogService } from '../../services/dialog_service'
import { openFilesService } from '../../services/open_files_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { telemetryService } from '../../services/telemetry/telemetry_service'
import { AffectsEditorDialog } from './affects_editor_dialog'
import { CardBodyPopover } from './card_body_popover'
import { cardPopupService } from '../../services/card_popup_service'
import { CardColumn } from './card_column'
import { CardDragOverlay } from './card_drag_overlay'
import { cardDragDropService } from './card_drag_drop_service'
import { resolveCardDragEvent } from './card_drag'
import { useCardViewColumns } from './use_card_view_columns'

const DRAG_ACTIVATION_DISTANCE = 2
interface CardViewProps {
    cardTypes: CardTypeConfig[]
    states: StateConfig[]
    statusColors: Map<string, string>
}

async function runCardEdit(action: () => unknown, fallbackMessage: string) {
    try {
        await action()
    } catch (error) {
        dialogService.error(error, { fallbackMessage })
    }
}

function currentCardColumns(states: StateConfig[]) {
    const cards = dataService.getState().snapshot?.activeCards ?? []

    return buildCardColumns(cards, states)
}

/** Card view: status columns of draggable cards with card-anchored body popup access. */
export function CardView(props: CardViewProps) {
    const {
        cardTypes,
        states,
        statusColors,
    } = props
    const columns = useCardViewColumns(states)
    const [openAffectsPath, setOpenAffectsPath] = useState<string | null>(null)
    const rootElementRef = useRef<HTMLDivElement>(null)
    const dragColumnsRef = useRef<ReturnType<typeof currentCardColumns> | null>(null)
    const lastOverIdRef = useRef<string | null>(null)
    const missingRootReportedRef = useRef(false)
    const wasVisibleRef = useRef<boolean | null>(null)
    const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: DRAG_ACTIVATION_DISTANCE } }))

    const handleOpenAffects = (path: string) => {
        setOpenAffectsPath(path)
    }

    const handleCloseAffects = () => {
        setOpenAffectsPath(null)
    }

    const clearActiveCard = useCallback(() => {
        dragColumnsRef.current = null
        lastOverIdRef.current = null
        cardDragDropService.endDrag()
    }, [])

    useEffect(() => {
        const updateVisibility = () => {
            const rootElement = rootElementRef.current
            if (!rootElement) {
                if (!missingRootReportedRef.current) {
                    missingRootReportedRef.current = true
                    dialogService.error(new Error('Missing card view root element'), {fallbackMessage: 'Card view could not be displayed'})
                }
                return
            }

            const isVisible = workspaceViewService.getSnapshot().viewMode === 'cards'
            rootElement.style.display = isVisible ? 'flex' : 'none'
            if (wasVisibleRef.current === isVisible) return

            wasVisibleRef.current = isVisible
            if (isVisible) return

            queueMicrotask(() => {
                cardPopupService.closeCardDetails()
                setOpenAffectsPath((currentPath) => currentPath === null ? currentPath : null)
                clearActiveCard()
            })
        }

        updateVisibility()
        workspaceViewService.addEventListener('changed', updateVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateVisibility)
    }, [clearActiveCard])

    useEffect(() => () => cardPopupService.closeCardDetails(), [])

    const handleDragStart = useCallback((event: DragStartEvent) => {
        dragColumnsRef.current = currentCardColumns(states)
        lastOverIdRef.current = null
        cardDragDropService.startDrag(
            String(event.active.id),
            event.active.rect.current.initial?.height ?? null,
            event.active.rect.current.initial?.width ?? null,
        )
    }, [states])

    const handleDragOver = useCallback((event: DragOverEvent) => {
        const { active, over } = event
        const overId = over ? String(over.id) : null
        if (lastOverIdRef.current === overId) return

        lastOverIdRef.current = overId
        if (!over) {
            cardDragDropService.setDropPreview(null)
            return
        }

        const dragColumns = dragColumnsRef.current
        if (!dragColumns) throw new Error('Cannot update a card drop target before dragging starts')

        const drop = resolveCardDragEvent(dragColumns, event)
        const sourceColumn = dragColumns.find((column) => column.cards.some((card) => card.path === String(active.id)))
        const dropPreview = drop && sourceColumn?.status !== drop.targetStatus ? drop : null
        cardDragDropService.setDropPreview(dropPreview)
    }, [])

    const handleDragEnd = useCallback((event: DragEndEvent) => {
        const { active, over } = event
        const drop = over ? resolveCardDragEvent(currentCardColumns(states), event) : null
        const path = String(active.id)
        if (!drop) {
            clearActiveCard()
            return
        }

        clearActiveCard()
        void runCardEdit(() => dataService.cards.moveCard(path, drop.targetStatus, drop.targetIndex), `Card move failed: ${path}`)
    }, [clearActiveCard, states])

    const handleOpenInFileMode = (path: string) => {
        cardPopupService.closeCardDetails()
        workspaceViewService.selectPath(path)
        void runCardEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)
        workspaceViewService.setViewMode('text')
        telemetryService.trackEvent('navigation')
    }

    const handleDeleteCard = async (path: string) => {
        try {
            await dataService.cards.deleteCard(path)
            workspaceViewService.clearSelectedPath(path)
            cardPopupService.closeCardDetailsPath(path)
            if (openAffectsPath === path) handleCloseAffects()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Card delete failed: ${path}` })
            throw error
        }
    }

    const handleTitleChange = (path: string, title: string) => {
        dataService.cards.updateCardTitle(path, title).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: `Title update failed: ${path}` })
        })
    }

    const handleTogglePolicy = (path: string, policyKey: string) => {
        void runCardEdit(() => dataService.cards.toggleCardPolicy(path, policyKey), `Policy toggle failed: ${path}`)
    }

    const handleAffectsChange = (path: string, affects: string[]) => {
        void runCardEdit(() => dataService.cards.updateCardAffects(path, affects), `Affects update failed: ${path}`)
    }

    return (
        <Box
            ref={rootElementRef}
            sx={{ bgcolor: 'background.default', display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden', position: 'relative' }}
        >
            <DndContext
                collisionDetection={closestCorners}
                onDragCancel={clearActiveCard}
                onDragEnd={handleDragEnd}
                onDragOver={handleDragOver}
                onDragStart={handleDragStart}
                sensors={sensors}
            >
                <Box
                    aria-label="Card columns"
                    sx={{
                        alignItems: 'flex-start',
                        display: 'flex',
                        flex: 1,
                        flexDirection: 'row',
                        gap: 2,
                        height: '100%',
                        overflowX: 'auto',
                        overflowY: 'auto',
                        p: 2.5,
                    }}
                >
                    {columns.map((column) => (
                        <CardColumn
                            key={column.status}
                            cardTypes={cardTypes}
                            column={column}
                            isMobile={false}
                            onDeleteCard={handleDeleteCard}
                            onOpenInFileMode={handleOpenInFileMode}
                            onTitleChange={handleTitleChange}
                            onTogglePolicy={handleTogglePolicy}
                        />
                    ))}
                </Box>
                <DragOverlay>
                    <CardDragOverlay cardTypes={cardTypes} />
                </DragOverlay>
                <CardBodyPopover
                    cardTypes={cardTypes}
                    isMobile={false}
                    onDeleteCard={handleDeleteCard}
                    onOpenAffects={handleOpenAffects}
                    onOpenInFileMode={handleOpenInFileMode}
                    statusColors={statusColors}
                    visible
                />
                <AffectsEditorDialog
                    cardPath={openAffectsPath}
                    onClose={handleCloseAffects}
                    onSave={handleAffectsChange}
                />
            </DndContext>
        </Box>
    )
}
import { Box } from '@mui/material'
import { DndContext, DragOverlay, MouseSensor, TouchSensor, closestCorners, useSensor, useSensors } from '@dnd-kit/core'
import type { DragEndEvent, DragMoveEvent, DragStartEvent } from '@dnd-kit/core'
import { useCallback, useEffect, useRef, useState } from 'react'
import { buildCardColumns } from '../../data/card_ordering'
import type { CardTypeConfig, StateConfig } from '../../data/data_types'
import { dataService } from '../../services/data/data_service'
import { dialogService } from '../../services/dialog_service'
import { openFilesService } from '../../services/open_files_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { telemetryService } from '../../services/telemetry/telemetry_service'
import { AffectsEditorDialog } from './affects_editor_dialog'
import { CardBodyPopover } from './card_body_popover'
import { cardPopupService } from '../../services/card_popup_service'
import { CardColumn } from './card_column'
import { CardDragOverlay } from './card_drag_overlay'
import { cardDragDropService } from './card_drag_drop_service'
import { useCardViewColumns } from './use_card_view_columns'
import { useMobileCardViewColumn } from './use_mobile_card_view_column'
import { resolveMobileCardDragEvent } from './mobile_card_drag'

const LONG_PRESS_DELAY_MS = 500
const LONG_PRESS_TOLERANCE = 5

interface MobileCardViewProps {
    cardTypes: CardTypeConfig[]
    states: StateConfig[]
    statusColors: Map<string, string>
}

async function runCardEdit(action: () => unknown, fallbackMessage: string) {
    try {
        await action()
    } catch (error) {
        dialogService.error(error, { fallbackMessage })
    }
}

function currentCardColumns(states: StateConfig[]) {
    const cards = dataService.getState().snapshot?.activeCards ?? []

    return buildCardColumns(cards, states)
}

/** Mobile board showing one selected column with delayed touch dragging. */
export function MobileCardView(props: MobileCardViewProps) {
    const { cardTypes, states, statusColors } = props
    const columns = useCardViewColumns(states)
    const selectedColumn = useMobileCardViewColumn(columns)
    const [openAffectsPath, setOpenAffectsPath] = useState<string | null>(null)
    const rootElementRef = useRef<HTMLDivElement>(null)
    const wasVisibleRef = useRef<boolean | null>(null)
    const sensors = useSensors(
        useSensor(MouseSensor, { activationConstraint: { delay: LONG_PRESS_DELAY_MS, tolerance: LONG_PRESS_TOLERANCE } }),
        useSensor(TouchSensor, { activationConstraint: { delay: LONG_PRESS_DELAY_MS, tolerance: LONG_PRESS_TOLERANCE } }),
    )

    const clearActiveCard = useCallback(() => {
        cardDragDropService.endDrag()
    }, [])

    const handleCloseAffects = () => {
        setOpenAffectsPath(null)
    }

    useEffect(() => {
        const updateVisibility = () => {
            const rootElement = rootElementRef.current
            if (!rootElement) return

            const isVisible = workspaceViewService.getSnapshot().viewMode === 'cards'
            rootElement.style.display = isVisible ? 'flex' : 'none'
            if (wasVisibleRef.current === isVisible) return

            wasVisibleRef.current = isVisible
            if (isVisible) return

            queueMicrotask(() => {
                cardPopupService.closeCardDetails()
                setOpenAffectsPath((currentPath) => currentPath === null ? currentPath : null)
                clearActiveCard()
            })
        }

        updateVisibility()
        workspaceViewService.addEventListener('changed', updateVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateVisibility)
    }, [clearActiveCard])

    useEffect(() => () => cardPopupService.closeCardDetails(), [])

    const handleDragStart = useCallback((event: DragStartEvent) => {
        cardDragDropService.startDrag(
            String(event.active.id),
            event.active.rect.current.initial?.height ?? null,
            event.active.rect.current.initial?.width ?? null,
        )
    }, [])

    const handleDragMove = useCallback((event: DragMoveEvent) => {
        if (!selectedColumn) return

        cardDragDropService.setDropPreview(resolveMobileCardDragEvent(currentCardColumns(states), selectedColumn.status, event))
    }, [selectedColumn, states])

    const handleDragEnd = useCallback((event: DragEndEvent) => {
        const drop = selectedColumn ? resolveMobileCardDragEvent(currentCardColumns(states), selectedColumn.status, event) : null
        clearActiveCard()
        const path = String(event.active.id)
        if (drop) void runCardEdit(() => dataService.cards.moveCard(path, drop.targetStatus, drop.targetIndex), `Card move failed: ${path}`)
    }, [clearActiveCard, selectedColumn, states])

    const handleOpenInFileMode = (path: string) => {
        cardPopupService.closeCardDetails()
        workspaceViewService.selectPath(path)
        void runCardEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)
        workspaceViewService.setViewMode('text')
        telemetryService.trackEvent('navigation')
    }

    const handleDeleteCard = async (path: string) => {
        try {
            await dataService.cards.deleteCard(path)
            workspaceViewService.clearSelectedPath(path)
            cardPopupService.closeCardDetailsPath(path)
            if (openAffectsPath === path) setOpenAffectsPath(null)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Card delete failed: ${path}` })
            throw error
        }
    }

    const handleTitleChange = (path: string, title: string) => {
        dataService.cards.updateCardTitle(path, title).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: `Title update failed: ${path}` })
        })
    }

    const handleTogglePolicy = (path: string, policyKey: string) => {
        void runCardEdit(() => dataService.cards.toggleCardPolicy(path, policyKey), `Policy toggle failed: ${path}`)
    }

    const handleAffectsChange = (path: string, affects: string[]) => {
        void runCardEdit(() => dataService.cards.updateCardAffects(path, affects), `Affects update failed: ${path}`)
    }

    return (
        <Box
            aria-label="Mobile card board"
            ref={rootElementRef}
            sx={{ bgcolor: 'background.default', display: 'flex', flex: 1, minHeight: 0, overflowX: 'hidden', overflowY: 'auto' }}
        >
            <DndContext
                collisionDetection={closestCorners}
                onDragCancel={clearActiveCard}
                onDragEnd={handleDragEnd}
                onDragMove={handleDragMove}
                onDragStart={handleDragStart}
                sensors={sensors}
            >
                <Box aria-label="Mobile card column" sx={{ display: 'flex', flex: 1, minHeight: 0, width: '100%' }}>
                    {selectedColumn ? (
                        <CardColumn
                            cardTypes={cardTypes}
                            column={selectedColumn}
                            isMobile
                            onDeleteCard={handleDeleteCard}
                            onOpenInFileMode={handleOpenInFileMode}
                            onTitleChange={handleTitleChange}
                            onTogglePolicy={handleTogglePolicy}
                        />
                    ) : null}
                </Box>
                <DragOverlay><CardDragOverlay cardTypes={cardTypes} /></DragOverlay>
                <CardBodyPopover
                    cardTypes={cardTypes}
                    isMobile
                    onDeleteCard={handleDeleteCard}
                    onOpenAffects={setOpenAffectsPath}
                    onOpenInFileMode={handleOpenInFileMode}
                    statusColors={statusColors}
                    visible
                />
                <AffectsEditorDialog cardPath={openAffectsPath} onClose={handleCloseAffects} onSave={handleAffectsChange} />
            </DndContext>
        </Box>
    )
}

